(function(){
'use strict';
function init(root=document){
 const q=s=>root.querySelector(s),qa=s=>[...root.querySelectorAll(s)];
 const menu=q('.menu-toggle'),nav=q('#navigation');
 menu?.addEventListener('click',()=>{const open=menu.getAttribute('aria-expanded')!=='true';menu.setAttribute('aria-expanded',String(open));menu.setAttribute('aria-label',open?'Close navigation':'Open navigation');nav.classList.toggle('open',open)});
 nav?.addEventListener('keydown',e=>{if(e.key==='Escape'){nav.classList.remove('open');menu.setAttribute('aria-expanded','false');menu.focus()}});
 qa('[data-role]').forEach(b=>b.addEventListener('click',()=>qa('[data-role]').forEach(x=>{x.setAttribute('aria-pressed',String(x===b));q('#'+x.getAttribute('aria-controls')).hidden=x!==b})));
 const cards=qa('[data-feature-role]'),filters=qa('[data-filter]'),search=q('#feature-search');let filter='all';
 function filterFeatures(){const term=(search?.value||'').trim().toLocaleLowerCase();let count=0;cards.forEach(c=>{const show=(filter==='all'||c.dataset.featureRole===filter||c.dataset.featureRole==='everyone')&&c.textContent.toLocaleLowerCase().includes(term);c.hidden=!show;if(show)count++});if(q('#feature-count'))q('#feature-count').textContent=`${count} ${count===1?'feature':'features'} shown`;if(q('#feature-empty'))q('#feature-empty').hidden=count!==0;}
 filters.forEach(b=>b.addEventListener('click',()=>{filter=b.dataset.filter;filters.forEach(x=>x.setAttribute('aria-pressed',String(x===b)));filterFeatures()}));search?.addEventListener('input',filterFeatures);
 const journeys={
 record:[['Patient workspace','Add a sample report','Choose a supported PDF and enter its date and source. The app checks the file and looks for duplicates.','Original file kept with its source'],['Patient workspace','Keep the review state clear','The report appears as pending review. An upload is not automatically treated as verified clinical information.','Status: pending review'],['Care-team workspace','Review the information','An authorized clinician accepts or rejects the imported record. The decision and relevant history are kept.','Review decision recorded'],['Patient workspace','Return to the whole story','Open the record and original document. A report explanation, when available, remains a draft for professional review.','Record, source, and review state together']],
 visit:[['Patient workspace','Choose a clinician and time','Browse clinicians and select an open appointment. Final availability is checked when the booking is saved.','A sample time is selected'],['Booking checks','Confirm the visit','The app checks permission, schedules, exceptions, and conflicts. Repeating a successful request returns its existing result.','One local booking with visit details'],['Care-team workspace','Record the consultation','The assigned clinician opens the relevant chart, records observations, and saves a draft with medicine details where needed.','Draft saved for the visit'],['Care-team workspace','Finalize and follow up','Finalization saves the signed note and related changes together. Later corrections are added as amendments.','Signed visit history is preserved']],
 task:[['Demonstration rules','Identify a follow-up example','A predefined rule checks synthetic observations or overdue follow-up. This is a software demonstration, not a diagnosis.','One source event is identified'],['Care-team workspace','Give the work an owner','The task has a responsible staff member, priority, and state. Duplicate source events are checked.','Assigned follow-up with a visible state'],['Care-team workspace','Review or hand over','Authorized staff review, acknowledge, transfer, or escalate the task within their permissions.','The action is added to the task history'],['Care-team workspace','Record the outcome','The permitted staff member completes the task and records the outcome. Ownership, progress, and history remain traceable.','Completed work with an accountable history']]
 };let journey='record',step=0;
 function renderGuide(){const target=q('#guide-content');if(!target)return;const [role,title,copy,result]=journeys[journey][step];target.innerHTML=`<span class="eyebrow">${role}</span><h3>${title}</h3><p>${copy}</p><div class="guide-result"><span>Example result</span><strong>${result}</strong></div>`;q('#guide-position').textContent=`Step ${step+1} of 4`;q('#guide-dots').innerHTML=Array.from({length:4},(_,i)=>`<i class="${i<=step?'current':''}"></i>`).join('');q('#guide-prev').disabled=step===0;q('#guide-next').textContent=step===3?'Start again':'Next step →';}
 qa('[data-journey]').forEach(b=>b.addEventListener('click',()=>{journey=b.dataset.journey;step=0;qa('[data-journey]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));renderGuide()}));q('#guide-prev')?.addEventListener('click',()=>{step=Math.max(0,step-1);renderGuide()});q('#guide-next')?.addEventListener('click',()=>{step=(step+1)%4;renderGuide()});renderGuide();
 const form=q('#contact-form');form?.addEventListener('submit',e=>{e.preventDefault();if(!form.reportValidity())return;const f=new FormData(form);const body=`Name: ${f.get('name')}\nEmail: ${f.get('email')}\n\n${f.get('message')}`;window.location.href=`mailto:myhealthcare.bh@gmail.com?subject=${encodeURIComponent('myhealth: '+f.get('topic'))}&body=${encodeURIComponent(body)}`;q('#form-status').textContent='Your email app should open with the draft. No message has been sent by this website. If it does not open, email myhealthcare.bh@gmail.com directly.'});
 q('[data-copy-email]')?.addEventListener('click',async()=>{try{if(!navigator.clipboard)throw Error();await navigator.clipboard.writeText('myhealthcare.bh@gmail.com');q('#copy-status').textContent='Email address copied.'}catch{q('#copy-status').textContent='Select and copy the email address above.'}});
 const picker=q('[data-video-file]'),stage=q('[data-video-stage]'),status=q('[data-video-status]'),reset=q('[data-video-reset]');
 if(picker&&stage){const initial=stage.innerHTML;let objectUrl=null;const revoke=()=>{if(objectUrl){URL.revokeObjectURL(objectUrl);objectUrl=null}};picker.addEventListener('change',()=>{const file=picker.files[0];if(!file)return;if(!file.type.startsWith('video/')){status.textContent='Choose a video file, such as an MP4.';picker.value='';return}revoke();const player=document.createElement('video');player.controls=true;player.playsInline=true;player.preload='metadata';player.setAttribute('aria-label','Your local video preview');objectUrl=URL.createObjectURL(file);player.src=objectUrl;player.addEventListener('error',()=>status.textContent='This browser could not play this video. Try an H.264 MP4.');stage.replaceChildren(player);status.textContent=`Previewing ${file.name} on this device only.`;reset.hidden=false});reset.addEventListener('click',()=>{revoke();stage.innerHTML=initial;picker.value='';reset.hidden=true;status.textContent='Local video preview removed.'});window.addEventListener('pagehide',revoke,{once:true});}
}
window.MyHealthSite={init};
if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',()=>init());else init();
})();
